CREATE TABLE "gallery_downloaded_v2" ("gid" INTEGER NOT NULL, "token" TEXT NOT NULL, "title" TEXT NOT NULL, "category" TEXT NOT NULL, "page_count" INTEGER NOT NULL, "gallery_url" TEXT NOT NULL, "old_version_gallery_url" TEXT NULL, "uploader" TEXT NULL, "publish_time" TEXT NOT NULL, "download_status_index" INTEGER NOT NULL, "insert_time" TEXT NOT NULL, "download_original_image" INTEGER NOT NULL DEFAULT 0 CHECK ("download_original_image" IN (0, 1)), "priority" INTEGER NOT NULL, "sort_order" INTEGER NOT NULL DEFAULT 0, "group_name" TEXT NOT NULL, "tags" TEXT NOT NULL DEFAULT '', "tag_refresh_time" TEXT NULL, "sanitized_title" TEXT NULL, PRIMARY KEY ("gid"));

CREATE TABLE "archive_downloaded_v2" ("gid" INTEGER NOT NULL, "token" TEXT NOT NULL, "title" TEXT NOT NULL, "category" TEXT NOT NULL, "page_count" INTEGER NOT NULL, "gallery_url" TEXT NOT NULL, "cover_url" TEXT NOT NULL, "uploader" TEXT NULL, "size" INTEGER NOT NULL, "publish_time" TEXT NOT NULL, "archive_status_index" INTEGER NOT NULL, "archive_page_url" TEXT NOT NULL, "download_page_url" TEXT NULL, "download_url" TEXT NULL, "is_original" INTEGER NOT NULL CHECK ("is_original" IN (0, 1)), "insert_time" TEXT NOT NULL, "sort_order" INTEGER NOT NULL DEFAULT 0, "group_name" TEXT NOT NULL, "tags" TEXT NOT NULL DEFAULT '', "tag_refresh_time" TEXT NULL, "parse_source" INTEGER NOT NULL DEFAULT 0, "sanitized_title" TEXT NULL, PRIMARY KEY ("gid"));
